import { onOptionsChange, options } from "./options";

/**
 * Sound, generated by code (Web Audio): no audio files yet. Short effects and a quiet generative music per place
 * (a Japanese pentatonic "in" scale over a drone). Browsers only allow sound after a first click or key press.
 */

export type Track = "intro" | "title" | "world" | "deck" | "duel";
export type Sfx = "click" | "blip" | "card" | "hit" | "win" | "lose" | "coin" | "choose";

let ac: AudioContext | null = null;
let master: GainNode | null = null;
let musicBus: GainNode | null = null;
let sfxBus: GainNode | null = null;
let wanted: Track | null = null;
let playing: Track | null = null;
let timer = 0;
let drone: { stop: () => void } | null = null;

function ready(): AudioContext | null {
  if (ac) return ac;
  const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  if (!Ctor) return null;
  ac = new Ctor();
  master = ac.createGain();
  musicBus = ac.createGain();
  sfxBus = ac.createGain();
  musicBus.connect(master);
  sfxBus.connect(master);
  master.connect(ac.destination);
  applyVolumes();
  return ac;
}

function applyVolumes(): void {
  if (!ac || !master || !musicBus || !sfxBus) return;
  master.gain.setTargetAtTime((options.volume / 100) * 0.5, ac.currentTime, 0.05);
  musicBus.gain.setTargetAtTime(options.music ? 0.5 : 0, ac.currentTime, 0.2);
  sfxBus.gain.setTargetAtTime(options.sfx ? 1 : 0, ac.currentTime, 0.05);
}
onOptionsChange(applyVolumes);

// The first gesture unlocks audio and starts the wanted music.
const unlock = () => {
  const a = ready();
  if (!a) return;
  void a.resume();
  if (wanted && playing !== wanted) startTrack(wanted);
};
window.addEventListener("pointerdown", unlock);
window.addEventListener("keydown", unlock);

function tone(freq: number, at: number, dur: number, type: OscillatorType, gain: number, bus: GainNode, slideTo?: number): void {
  if (!ac) return;
  const o = ac.createOscillator();
  const g = ac.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, at);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, at + dur);
  g.gain.setValueAtTime(0.0001, at);
  g.gain.exponentialRampToValueAtTime(gain, at + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
  o.connect(g).connect(bus);
  o.start(at);
  o.stop(at + dur + 0.05);
}

/** A short sound effect. */
export function sfx(name: Sfx): void {
  if (!options.sfx || !ready() || !ac || !sfxBus) return;
  const t = ac.currentTime;
  switch (name) {
    case "click": tone(520, t, 0.06, "square", 0.08, sfxBus); break;
    case "blip": tone(740 + Math.random() * 120, t, 0.04, "square", 0.05, sfxBus); break;
    case "choose": tone(660, t, 0.07, "triangle", 0.12, sfxBus); tone(990, t + 0.06, 0.1, "triangle", 0.12, sfxBus); break;
    case "card": tone(300, t, 0.12, "triangle", 0.15, sfxBus, 600); break;
    case "hit": tone(180, t, 0.18, "sawtooth", 0.18, sfxBus, 50); break;
    case "coin": tone(988, t, 0.08, "square", 0.08, sfxBus); tone(1319, t + 0.08, 0.2, "square", 0.08, sfxBus); break;
    case "win": [523, 659, 784, 1047].forEach((f, k) => tone(f, t + k * 0.12, 0.3, "triangle", 0.15, sfxBus!)); break;
    case "lose": [392, 349, 311, 262].forEach((f, k) => tone(f, t + k * 0.18, 0.4, "triangle", 0.14, sfxBus!)); break;
  }
}

// ------------------------------------------------------------------ music
/** In-sen scale degrees (semitones above the root): D, Eb, G, A, Bb. */
const SCALE = [0, 1, 5, 7, 8];
interface Feel {
  root: number;
  beat: number;
  density: number;
  pulse: boolean;
  pad: number;
}
const FEEL: Record<Track, Feel> = {
  intro: { root: 130.81, beat: 0.6, density: 0.35, pulse: false, pad: 0.06 },
  title: { root: 146.83, beat: 0.55, density: 0.45, pulse: false, pad: 0.07 },
  world: { root: 146.83, beat: 0.5, density: 0.5, pulse: false, pad: 0.05 },
  deck: { root: 164.81, beat: 0.5, density: 0.3, pulse: false, pad: 0.04 },
  duel: { root: 110, beat: 0.28, density: 0.55, pulse: true, pad: 0.07 },
};

const hz = (root: number, deg: number, oct = 0) => root * Math.pow(2, (SCALE[deg % 5] + 12 * (Math.floor(deg / 5) + oct)) / 12);

function startTrack(track: Track): void {
  stopMusic();
  if (!ready() || !ac || !musicBus) return;
  playing = track;
  const f = FEEL[track];
  const t0 = ac.currentTime;
  // drone: two soft detuned oscillators on the root and the fifth
  const nodes: OscillatorNode[] = [];
  const dg = ac.createGain();
  dg.gain.setValueAtTime(0.0001, t0);
  dg.gain.exponentialRampToValueAtTime(f.pad, t0 + 2);
  const lp = ac.createBiquadFilter();
  lp.type = "lowpass";
  lp.frequency.value = 500;
  dg.connect(lp).connect(musicBus);
  for (const [mult, det] of [[0.5, -4], [0.5, 4], [0.75, 0]] as const) {
    const o = ac.createOscillator();
    o.type = "sawtooth";
    o.frequency.value = f.root * mult;
    o.detune.value = det;
    o.connect(dg);
    o.start();
    nodes.push(o);
  }
  drone = {
    stop() {
      const t = ac!.currentTime;
      dg.gain.cancelScheduledValues(t);
      dg.gain.setTargetAtTime(0.0001, t, 0.3);
      for (const o of nodes) o.stop(t + 1.5);
    },
  };
  // melody: random plucks on the scale, scheduled a little ahead
  let next = t0 + 0.5;
  let step = 0;
  let deg = 5;
  timer = window.setInterval(() => {
    if (!ac || !musicBus) return;
    while (next < ac.currentTime + 0.6) {
      if (Math.random() < f.density) {
        deg = Math.max(0, Math.min(11, deg + [-2, -1, -1, 0, 1, 1, 2][Math.floor(Math.random() * 7)]));
        tone(hz(f.root, deg, 1), next, f.beat * 2.2, "triangle", 0.1, musicBus);
      }
      if (f.pulse && step % 4 === 0) tone(90, next, 0.15, "sine", 0.25, musicBus, 40);
      if (f.pulse && step % 2 === 1) tone(hz(f.root, 0, 2), next, 0.05, "square", 0.03, musicBus);
      next += f.beat;
      step++;
    }
  }, 200);
}

export function stopMusic(): void {
  window.clearInterval(timer);
  drone?.stop();
  drone = null;
  playing = null;
}

/** Wants this music; starts at once if the browser allows sound, otherwise at the first click or key press. */
export function playMusic(track: Track): void {
  wanted = track;
  if (playing === track) return;
  if (ac && ac.state === "running") startTrack(track);
}
